package com.aistock.notification.alert;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import java.time.*;import java.sql.Timestamp;import java.util.*;import java.util.function.Supplier;import static com.aistock.notification.alert.AlertEvaluationRecords.*;
/** Durable original alert evidence binding; no remote I/O under owner/operation row locks. */
public final class AlertMarketUseOwner {
 private record Binding(AlertMarketUseClient.Request request,AlertMarketUseClient.Receipt receipt,boolean started,boolean acked){}
 private final AlertRuleRepository repo;private final AlertEvaluationStore store;private final ObjectMapper json;private final AlertMarketUseClient client;private final Clock clock;private final boolean enabled;
 public AlertMarketUseOwner(AlertRuleRepository repo,ObjectMapper json,AlertMarketUseClient client,Clock clock,boolean enabled){this.repo=repo;this.store=new AlertEvaluationStore(repo,clock);this.json=json;this.client=client;this.clock=clock;this.enabled=enabled;}
 public boolean enabled(){return enabled;}
 public AlertMarketUseContext.Scope acquire(UUID owner,EvaluateRequest request,Supplier<AlertEvidenceClient.Reference> metadata){if(!enabled)return AlertMarketUseContext.empty();store.useInput(owner,request);client.requireReady();var b=read(request.operationId());if(b==null){var ref=metadata.get();b=prepare(owner,request,ref);}if(b.receipt()==null){AlertMarketUseClient.Receipt receipt;if(b.started())receipt=client.find(b.request()).orElseThrow(AlertMarketUseClient::unavailable);else if(start(owner,request))receipt=client.register(b.request());else receipt=client.find(b.request()).orElseThrow(AlertMarketUseClient::unavailable);attach(request.operationId(),receipt);b=read(request.operationId());}store.useInput(owner,request);return AlertMarketUseContext.open(b.request(),b.receipt());}
 private Binding prepare(UUID owner,EvaluateRequest request,AlertEvidenceClient.Reference ref){return repo.locked(owner,()->{String stock=store.useInput(owner,request);if(ref==null||!request.evidenceId().equals(ref.evidenceId())||!stock.equals(ref.instrumentId())||ref.rawVersionId()==null)throw AlertMarketUseClient.invalid();var old=read(request.operationId());if(old!=null){if(!old.request().rawVersionId().equals(ref.rawVersionId().toString()))throw AlertMarketUseClient.invalid();return old;}repo.jdbc().update("insert into alert_evaluation_market_use(operation_id,owner_id,evidence_id,instrument_id,raw_version_id,market_request_id,created_at,last_checked_at) values(?,?,?,?,?,?,?,?)",request.operationId().toString(),owner.toString(),request.evidenceId().toString(),stock,ref.rawVersionId().toString(),UUID.randomUUID().toString(),ts(),ts());return read(request.operationId());});}
 private boolean start(UUID owner,EvaluateRequest request){return Boolean.TRUE.equals(repo.locked(owner,()->{store.useInput(owner,request);return repo.jdbc().update("update alert_evaluation_market_use set registration_started=true where operation_id=? and registration_started=false",request.operationId().toString())==1;}));}
 private Binding read(UUID operation){var rows=repo.jdbc().queryForList("select * from alert_evaluation_market_use where operation_id=?",operation.toString());if(rows.isEmpty())return null;var row=rows.get(0);try{return new Binding(new AlertMarketUseClient.Request(operation.toString(),"1",row.get("market_request_id").toString(),row.get("raw_version_id").toString()),row.get("receipt_json")==null?null:json.readValue(row.get("receipt_json").toString(),AlertMarketUseClient.Receipt.class),Boolean.TRUE.equals(row.get("registration_started")),Boolean.TRUE.equals(row.get("completion_acked")));}catch(java.io.IOException e){throw AlertMarketUseClient.invalid();}}
 private void attach(UUID op,AlertMarketUseClient.Receipt receipt){var owners=repo.jdbc().queryForList("select owner_id from alert_evaluation_market_use where operation_id=?",String.class,op.toString());if(owners.size()!=1)throw AlertMarketUseClient.invalid();repo.locked(UUID.fromString(owners.get(0)),()->{repo.jdbc().queryForMap("select * from alert_evaluation_market_use where operation_id=? for update",op.toString());var b=read(op);if(b==null||!b.started()||!b.request().selector().versionIds().equals(receipt.versionIds()))throw AlertMarketUseClient.invalid();if(b.receipt()!=null){if(!b.receipt().bundleId().equals(receipt.bundleId())||!b.receipt().versionIds().equals(receipt.versionIds()))throw AlertMarketUseClient.invalid();return null;}repo.jdbc().update("update alert_evaluation_market_use set bundle_id=?,receipt_json=? where operation_id=? and bundle_id is null",receipt.bundleId(),encode(receipt),op.toString());return null;});}
 public JsonNode proof(UUID operation,String generation){if(!"1".equals(generation))throw AlertMarketUseClient.unavailable();var terminal=store.terminal(operation);var b=read(operation);if(b==null||b.receipt()==null)throw AlertMarketUseClient.unavailable();var n=((ObjectNode)terminal).deepCopy();n.put("owner","notification").put("purpose","ALERT_EVALUATION").put("ownerOperationId",operation.toString()).put("generation","1");n.set("versionIds",json.valueToTree(b.receipt().versionIds()));return n;}
 public void notifyCompleted(UUID operation){if(!enabled)return;try{var b=read(operation);if(b==null||b.receipt()==null||b.acked())return;proof(operation,"1");mark(operation.toString());var release=client.complete(b.request(),b.receipt());if(release==null||!"RELEASED".equals(release.state())||!b.receipt().bundleId().equals(release.bundleId())||!b.receipt().versionIds().equals(release.versionIds()))throw AlertMarketUseClient.invalid();repo.jdbc().update("update alert_evaluation_market_use set completion_acked=true where operation_id=? and bundle_id=?",operation.toString(),b.receipt().bundleId());}catch(RuntimeException ignored){/* Immutable result remains; never infer release. */}}
 public void recoverOne(UUID operation){if(!enabled)return;try{mark(operation.toString());var b=read(operation);if(b==null||b.acked()||!b.started())return;if(b.receipt()==null){var receipt=client.find(b.request());if(receipt.isEmpty())return;attach(operation,receipt.get());}notifyCompleted(operation);}catch(RuntimeException ignored){/* Never POST again or recompute. */}}
 public void recoverBatch(){if(!enabled)return;for(var id:repo.jdbc().queryForList("select operation_id from alert_evaluation_market_use where registration_started=true and completion_acked=false order by last_checked_at,operation_id limit 25",String.class)){mark(id);try{recoverOne(UUID.fromString(id));}catch(RuntimeException ignored){/* Corrupt keys rotate conservatively. */}}}
 private void mark(String op){repo.jdbc().update("update alert_evaluation_market_use set last_checked_at=greatest(?,timestampadd(microsecond,1000,last_checked_at)) where operation_id=?",ts(),op);}private Timestamp ts(){return Timestamp.from(clock.instant());}private String encode(Object value){try{return json.writeValueAsString(value);}catch(java.io.IOException e){throw AlertMarketUseClient.invalid();}}
}
